{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "AKBA, an acetylated triterpenoid acid with a carboxylic acid and acetate, showed poor oral bioavailability in healthy volunteers; this functional pattern is the closest match to the query's acetylated terpenoid acid and supports F<20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Medroxyprogesterone acetate, the highest-similarity analogue, has oral bioavailability probably less than 15% in humans due to gut and liver metabolism, supporting low F for the acetate-containing polycyclic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Nestorone, a steroidal acetate, has low oral bioavailability in women due to rapid gastrointestinal and hepatic inactivation, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "16-Acetyl-gitoxin showed 98.6% absolute oral bioavailability in healthy volunteers, providing high-F evidence, but its cardiac glycoside/sugar structure limits transferability to the non-glycoside query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C15"],
      "claim": "Chenodeoxycholic acid, a carboxylic acid-containing steroid, showed complete or 81% systemic bioavailability in humans, but this is mediated by bile-acid transport and enterohepatic circulation, which are not expected for the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C17"],
      "claim": "Chlormadinone acetate had approximately 100% oral bioavailability in humans, showing that acetate steroids can be well absorbed; however, it lacks the query's ionized carboxylic acid and higher molecular weight.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The query is a high-MW, ionized diterpenoid acid with acetate and hydroxyls. The most transferable experimental evidence—acetylated terpenoid/steroid acids such as AKBA, MPA, and Nestorone—indicates poor or low oral bioavailability. High-F cardiac glycosides and bile acids are less transferable because their absorption depends on sugar moieties or active bile-acid transporters. Therefore, F<20% is better supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the query molecule.",
    "All evidence analogues have low Morgan similarity (<0.27), limiting quantitative transferability.",
    "No data address whether the query is a substrate for intestinal transporters or how its prenyl side chain and acetate hydrolysis affect absorption and first-pass metabolism."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

